    def check(obj, attr, msg):
        if not hasattr(obj, attr):
            raise Exception(f"NotFittedError: {msg % {'name': type(obj).__name__}}")

class MockVectorizer:
    """Simulates CountVectorizer behavior"""
    def __init__(self, vocabulary=None):
        self.vocabulary = vocabulary

    def _validate_vocabulary(self):
        vocabulary = self.vocabulary
        if vocabulary is not None:
            if isinstance(vocabulary, set):
                vocabulary = sorted(vocabulary)
            if not isinstance(vocabulary, dict):
                vocab = {}
                for i, t in enumerate(vocabulary):
                    if vocab.setdefault(t, i) != i:
                        raise ValueError("Duplicate term in vocabulary: %r" % t)
                vocabulary = vocab
            if not vocabulary:
                raise ValueError("empty vocabulary passed to fit")
            self.fixed_vocabulary_ = True
            self.vocabulary_ = dict(vocabulary)
        else:
            self.fixed_vocabulary_ = False

    def _check_vocabulary(self):
        """Check if vocabulary is empty or missing (not fit-ed)"""
        msg = "%(name)s - Vocabulary wasn't fitted."
        MockCheckIsFitted.check(self, 'vocabulary_', msg)
        if len(self.vocabulary_) == 0:
            raise ValueError("Vocabulary is empty")

    def get_feature_names_old(self):
        """OLD version - only calls _check_vocabulary"""
        self._check_vocabulary()
        return [t for t, i in sorted(self.vocabulary_.items(), key=itemgetter(1))]

    def get_feature_names(self):
        """NEW version - calls _validate_vocabulary first if needed"""
        if not hasattr(self, 'vocabulary_'):
            self._validate_vocabulary()
        self._check_vocabulary()
        return [t for t, i in sorted(self.vocabulary_.items(), key=itemgetter(1))]

